// ============================================================================
// OFFLINE FONT / ICON GUARD
//
// The built single-file app must render correctly with NO network. Previously it
// pulled Outfit from fonts.googleapis.com and the RemixIcon face from jsdelivr,
// so with no connection every icon collapsed to a blank box. Those are now
// embedded as base64 data: URIs in assets/offline-fonts.css, generated by
// scripts/build-offline-assets.mjs.
//
// Two ways that silently regresses, both guarded here:
//  1. Someone adds a new `ri-*` icon and doesn't re-run the generator — the class
//     has no rule in the stylesheet, so it renders as nothing.
//  2. Someone reintroduces a CDN <link> (or an icon name that isn't in RemixIcon
//     at all, which is how ri-drops-line / ri-hand-wash-fill shipped invisible).
//
// Regenerate with:  node scripts/build-offline-assets.mjs
// ============================================================================
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(__dirname, '..');
const CSS_PATH = path.join(ROOT, 'assets', 'offline-fonts.css');

let passed = 0, failed = 0;
const check = (name, cond) => {
    if (cond) { passed++; console.log(`✅ [PASS] ${name}`); }
    else { failed++; console.log(`❌ [FAIL] ${name}`); }
};

// ── Collect every ri-* class the app references ──────────────────────────────
// Mirrors the generator's scan: markup, styles, factories, AND modules/data.js
// (category icons live in data, not templates).
const sourceFiles = [];
const walk = (dir) => {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        if (e.name === 'node_modules' || e.name.startsWith('.')) continue;
        const p = path.join(dir, e.name);
        if (e.isDirectory()) walk(p);
        else if (/\.(js|html|css|json)$/.test(e.name)) sourceFiles.push(p);
    }
};
walk(path.join(ROOT, 'modules'));
for (const f of ['index.html', 'index.css', 'app.js']) sourceFiles.push(path.join(ROOT, f));

const used = new Set();
for (const f of sourceFiles) {
    for (const m of fs.readFileSync(f, 'utf8').matchAll(/\bri-[a-z0-9-]+/g)) used.add(m[0]);
}

check('assets/offline-fonts.css exists (run scripts/build-offline-assets.mjs)',
    fs.existsSync(CSS_PATH));
if (!fs.existsSync(CSS_PATH)) {
    console.log('\nSummary: 0 passed, 1 failed.');
    process.exit(1);
}
const css = fs.readFileSync(CSS_PATH, 'utf8');

// ── 1. Every referenced icon must have a glyph rule ──────────────────────────
const defined = new Set([...css.matchAll(/\.(ri-[a-z0-9-]+):before/g)].map((m) => m[1]));
const undefinedIcons = [...used].filter((u) => !defined.has(u)).sort();
check(`every referenced ri-* icon has a rule (${used.size} referenced, ${defined.size} defined)`,
    undefinedIcons.length === 0);
if (undefinedIcons.length) {
    console.log('        missing glyphs (these render blank):');
    for (const i of undefinedIcons) console.log(`          ${i}`);
    console.log('        -> fix the name, or re-run: node scripts/build-offline-assets.mjs');
}

// ── 2. Fonts must be embedded, not fetched ───────────────────────────────────
check('remixicon face is embedded as a data: URI',
    /@font-face[^}]*font-family:\s*'remixicon'[^}]*url\(data:font\/woff2;[^)]*base64,/s.test(css));
check('Outfit face is embedded as a data: URI',
    /@font-face[^}]*font-family:\s*'Outfit'[^}]*url\(data:font\/woff2;[^)]*base64,/s.test(css));
check('stylesheet fetches nothing over the network',
    !/url\(\s*['"]?https?:/i.test(css));

// ── 3. No CDN stylesheet links may come back into index.html ─────────────────
const indexHtml = fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8');
check('index.html has no Google Fonts <link>', !/fonts\.googleapis\.com/.test(indexHtml));
check('index.html has no jsdelivr <link>', !/cdn\.jsdelivr\.net/.test(indexHtml));
check('index.html links the generated stylesheet',
    /href=["']assets\/offline-fonts\.css/.test(indexHtml));

// ── 4. The print/export window must not @import a webfont either ─────────────
const appJs = fs.readFileSync(path.join(ROOT, 'app.js'), 'utf8');
check('print window does not @import a webfont',
    !/@import\s+url\(['"]?https?:\/\/fonts\./.test(appJs));

console.log('\n--------------------------------------------------');
console.log(`Summary: ${passed} passed, ${failed} failed.`);
console.log('--------------------------------------------------');
if (failed > 0) process.exit(1);
